function XUiEquipPartnerOneClickPopup:_RefreshCostMoney()
    local itemIds = XDataCenter.ItemManager.ItemId
    local commitControl = self._Control:GetOneKeyCultureMainControl():GetCommitControl()

    -- 螺母
    local coinCost = self:_GetCostMoney(commitControl:GetLevelUpConsumedList(), itemIds.Coin)
        + self:_GetCostMoney(commitControl:GetStarUpConsumedList(), itemIds.Coin)
        + self:_GetCostMoney(commitControl:GetSkillConsumedList(), itemIds.Coin)
    self:_RefreshCostItem(self.GoConsume1, self.RImgConsume1, self.TxtCostMoney1, itemIds.Coin, coinCost)

    local exchangeList = self:_BuildExchangeTipList()

    -- 拟战积分
    local repeatChallengeCoinCost = 0
    for _, exchange in ipairs(exchangeList) do
        repeatChallengeCoinCost = repeatChallengeCoinCost + self:_GetCostMoney(exchange.ConsumeList, itemIds.RepeatChallengeCoin)
    end
    self:_RefreshCostItem(self.GoConsume2, self.RImgConsume2, self.TxtCostMoney2, itemIds.RepeatChallengeCoin, repeatChallengeCoinCost)

    -- 钛矿
    local tantalumIronOreCost = 0
    for _, exchange in ipairs(exchangeList) do
        tantalumIronOreCost = tantalumIronOreCost + self:_GetCostMoney(exchange.ConsumeList, itemIds.TantalumIronOre)
    end
    self:_RefreshCostItem(self.GoConsume3, self.RImgConsume3, self.TxtCostMoney3, itemIds.TantalumIronOre, tantalumIronOreCost)
end

