--- 汇总本次提交涉及的兑换材料，供 UiRoleExchangeTipPopup 展示
--- 数据项格式：{ItemId(产物), RewardCount(总产出), ConsumeList={{Id(代币), Count(总消耗)}}}
---@return table[]
function XUiEquipPartnerOneClickPopup:_BuildExchangeTipList()
    local mainControl = self._Control:GetOneKeyCultureMainControl()
    local commitControl = mainControl:GetCommitControl()
    local exchangeList = self._ExchangeTipList
    local mergedDic = self._ExchangeMergedDic
    table.clear(exchangeList)
    table.clear(mergedDic)

    -- 自动兑换计划（拟战代币兑换养成材料），同一产物可能有多条计划，按 ItemId 合并
    for _, plan in ipairs(commitControl:GetExchangePlanList()) do
        local merged = mergedDic[plan.ItemId]
        if not merged then
            merged = { ItemId = plan.ItemId, RewardCount = 0, ConsumeCountDic = {} }
            mergedDic[plan.ItemId] = merged
            table.insert(exchangeList, merged)
        end
        merged.RewardCount = merged.RewardCount + plan.GainCount
        for _, consume in ipairs(plan.ConsumeList) do
            merged.ConsumeCountDic[consume.ConsumeId] = (merged.ConsumeCountDic[consume.ConsumeId] or 0) + consume.ConsumeCount * plan.Times
        end
    end
    for _, merged in ipairs(exchangeList) do
        local consumeList = {}
        for consumeId, consumeCount in pairs(merged.ConsumeCountDic) do
            table.insert(consumeList, { Id = consumeId, Count = consumeCount })
        end
        table.sort(consumeList, function(a, b) return a.Id < b.Id end)
        merged.ConsumeList = consumeList
        merged.ConsumeCountDic = nil
    end

    -- 选中的钛矿（钽铁合矿）兑换碎片
    local needChipCount = commitControl:GetSelectOreExchangeChipCount()
    if needChipCount > 0 then
        local partner = mainControl:GetCurPartnerEntity()
        local chipNeedCount = partner and partner:GetChipNeedCount()
        if partner and XTool.IsNumberValid(chipNeedCount) then
            local chipItemId = partner:GetChipItemId()
            local _, exchangeChipCount, consumeId, consumeCount =
                XMVCA.XPartner.Util.GetOreExchangeChipCostByCount(chipItemId, needChipCount)
            if exchangeChipCount >= needChipCount then
                table.insert(exchangeList, {
                    ItemId = chipItemId,
                    RewardCount = exchangeChipCount,
                    ConsumeList = { { Id = consumeId, Count = consumeCount } },
                })
            else
                XLog.Error(string.format(
                    "XUiEquipPartnerOneClickPopup:_BuildExchangeTipList 无法满足碎片兑换需求, chipItemId=%s needChipCount=%s exchangeChipCount=%s",
                    tostring(chipItemId), tostring(needChipCount), tostring(exchangeChipCount)))
            end
        end
    end

    return exchangeList
end


---将代币数量缩写为 K，向下保留最多一位小数
---@param cost number
---@return string
function XUiEquipPartnerOneClickPopup:_FormatCost(cost)
    local KILO = 1000
    if cost < KILO then
        return tostring(cost)
    end

    local costInK = math.floor(cost / KILO * 10) / 10
    local costText = string.format("%.1f", costInK):gsub("%.0$", "")
    return costText .. "K"
end

return XUiEquipPartnerOneClickPopup
